R=Path(__file__).resolve().parents[3]; s='9702-9.1'; k=lambda n:f'{s}.{n}'
note='Subjects/9702 Physics/09 Electricity/9.1 Electric current.md'
p={'subtopic':s,'spec':'9702','version':1,'note':note,'outline':'Electric current is a flow of charge carriers. Their charges are integer multiples of the elementary charge $e=1.60\\times10^{-19}\\,\\mathrm C$. Charge passing a point in time $t$ is $Q=It$. In a conductor, the charge carriers in a length $vt$ cross area $A$ in time $t$; there are $nAvt$ carriers, so $I=Anvq$, where $n$ is number per unit volume and $q$ is charge magnitude per carrier. At fixed current and material, drift speed varies inversely with cross-sectional area.','misconceptions':[],'worked':[],'items':[],'flashcards':[],'diagrams':[]}
mis=[(1,'Current is a flow of energy rather than charge carriers.','Current is flow of charge carriers; energy transfer is a different quantity.','charge flow versus energy transfer','ER 9702 w24 P13 Q31'),(2,'Any fractional value of the elementary charge is possible.','A carrier charge is an integer multiple of $e$, including zero.','integer versus fractional multiple','ER 9702 s23 P12 Q30'),(3,'Charge passing a narrower section is smaller at constant current.','$Q=It$ gives the same charge in the same time at every section of a series wire.','charge versus cross-sectional area','ER 9702 s19 P12 Q33'),(4,'Number density means carriers per unit area.','$n$ counts carriers per unit volume; $nAvt$ is the number passing in time $t$.','volume versus area density','ER 9702 s21 P13 Q33'),(4,'Doubling diameter doubles area.','Area is proportional to diameter squared, so doubling diameter quadruples area.','diameter versus area ratio','ER 9702 s22 P13 Q32')]
