def short(n,cmd,stem,answer,d=2):
 i=sum(x['source']['type']=='generated' for x in p['items'])+1
 p['items'].append({'id':f'{s}-i{i:02d}','kcs':[k(n)],'kind':'short','difficulty':d,'command_word':cmd,'source':{'type':'generated'},'stem':f'{cmd} {stem}','marks':1,'rubric':[{'point':answer,'keywords':[[answer.split()[0]]]}],'explanation':answer,'hints':['Recall what physical quantity is involved.','Use the definition and identify the relevant variables.','Start by stating the defining relation.']})
sets={1:[('Define','electric current in terms of charge carriers.','Electric current is a flow of charge carriers.'),('Identify','the moving charge carriers in a metal.','Electrons are the moving charge carriers in a metal.'),('Identify','the moving charge carriers in an electrolyte.','Positive and negative ions carry current in an electrolyte.'),('Explain','why a neutron beam does not constitute an electric current.','Neutrons have no charge, so their motion transports no electric charge.'),('Compare','current in a metal and in an electrolyte.','Electrons carry current in a metal; ions carry current in an electrolyte.'),('Describe','what passes a fixed cross-section when there is current.','Charged particles cross the section, transferring charge.')],2:[('State','what is meant by quantisation of charge.','Charge on a carrier is an integer multiple of the elementary charge.'),('Determine','whether $4.8\\times10^{-19}$ C is a possible carrier charge.','It is possible because it equals $3e$.'),('Determine','whether $4.0\\times10^{-19}$ C is a possible carrier charge.','It is impossible because it equals $2.5e$, not an integer multiple.'),('Explain','why a negative ion can carry $-3.2\\times10^{-19}$ C.','It carries $-2e$, an integer multiple of elementary charge.'),('State','the elementary charge in coulombs.','The elementary charge is $1.60\\times10^{-19}$ C.'),('Explain','why an uncharged droplet does not violate quantisation.','Zero is an integer multiple of the elementary charge.')],3:[('State','the equation connecting charge, current and time.','$Q=It$, where charge is in coulombs, current in amperes and time in seconds.'),('Define','one coulomb using current and time.','One coulomb is the charge transferred by one ampere in one second.'),('Calculate','the charge transferred by 2 A in 3 s.','$Q=It=(2)(3)=6$ C.'),('Determine','the current when 12 C passes in 4 s.','$I=Q/t=12/4=3$ A.'),('Explain','why equal charge passes two sections of a steady series wire in equal time.','The steady current is equal at both sections, so $Q=It$ gives equal charge.'),('Calculate','the number of electrons in 3.2 C.','$N=Q/e=3.2/(1.60\\times10^{-19})=2.0\\times10^{19}$ electrons.')],4:[('State','what $n$ means in $I=Anvq$.','$n$ is the number of charge carriers per unit volume.'),('State','the SI unit of number density.','The SI unit of number density is $\\mathrm{m^{-3}}$.'),('Explain','why drift speed rises when a same-material wire narrows at constant current.','$I=Anvq$ is constant; $n$ and $q$ are fixed, so $v$ increases as $A$ falls.'),('Determine','the area ratio when a wire diameter is doubled.','Cross-sectional area increases by a factor of four because $A\\propto d^2$.'),('Explain','how $nAvt$ counts carriers crossing a section in time $t$.','The swept volume is $Avt$ and number density times volume gives $nAvt$ carriers.'),('Show (that)','the drift relation follows from charge crossing area $A$ in time $t$.','$Q=nAvtq$ and $I=Q/t$, hence $I=Anvq$.' ) ]}
for n,rows in sets.items():
 for cmd,stem,ans in rows:short(n,cmd,stem,ans,4 if cmd in ('Explain','Show (that)') else 2)
