 p['worked'].append({'id':f'we{j}','kc':k(n),'problem':problem,'steps':[{'do':f'State {formula}.','why':'Start from the syllabus equation.'},{'do':'Substitute the SI values, using $e=1.60\\times10^{-19}$ C where needed.','why':'Units must be consistent.'},{'do':f'Answer: {float(val):.2g} {unit}.','why':'Give a value and unit.','check':{'kind':'numeric','answer':{'value':float(val),'unit':unit,'sf_ok':[2,3]}}}],'faded':{'id':f'we{j}f','problem':faded,'answer':{'value':float(fval),'unit':unit,'sf_ok':[2,3]},'blank_from':1}})
